/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { AbelianGroup, Perm, PermutationGroup, RubikGroup, isUnsolved } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.combinatorics.named_groups", () => {
  it("G.is_group", () => {
    expect(sympyStr(PermutationGroup([new Perm([1, 2, 0, 3]), new Perm([0, 2, 3, 1])]).isGroup)).toBe('True');
  });
  it("G.is_group (2)", () => {
    expect(sympyStr(PermutationGroup([new Perm([1, 2, 3, 4, 5, 0])]).isGroup)).toBe('True');
  });
  it("G.order()", () => {
    expect(sympyStr(PermutationGroup([new Perm([1, 2, 3, 4, 5, 0])]).order())).toBe('6');
  });
  it("G.is_group (3)", () => {
    expect(sympyStr(PermutationGroup([new Perm([1, 2, 3, 4, 0]), new Perm([4, 3, 2, 1, 0])]).isGroup)).toBe('True');
  });
  it("RubikGroup(2).is_group", () => {
    expect(sympyStr(PermutationGroup([new Perm([0, 1, 19, 17, 6, 4, 7, 5, 2, 9, 3, 11, 12, 13, 14, 15, 16, 20, 18, 21, 10, 8, 22, 23]), new Perm([0, 5, 2, 7, 4, 21, 6, 23, 10, 8, 11, 9, 3, 13, 1, 15, 16, 17, 18, 19, 20, 14, 22, 12]), new Perm([0, 1, 2, 3, 4, 5, 18, 19, 8, 9, 6, 7, 12, 13, 10, 11, 16, 17, 14, 15, 22, 20, 23, 21])]).isGroup)).toBe('True');
  });
  it("G.is_group (4)", () => {
    expect(sympyStr(PermutationGroup([new Perm([1, 2, 3, 0]), new Perm([1, 0, 2, 3])]).isGroup)).toBe('True');
  });
  it("G.order() (2)", () => {
    expect(sympyStr(PermutationGroup([new Perm([1, 2, 3, 0]), new Perm([1, 0, 2, 3])]).order())).toBe('24');
  });
  it("AbelianGroup(3, 4)", () => {
    expect(sympyStr(AbelianGroup(3, 4))).toBe('PermutationGroup([\n    (6)(0 1 2),\n    (3 4 5 6)])');
  });
});

